 [(("पेंशन", "Pension"), ("कम से कम ₹3,000 प्रति माह (60 साल के बाद)", "At least ₹3,000 a month (after 60)")), (("प्रवेश उम्र", "Entry age"), ("18 से 40 साल", "18 to 40 years")), (("अंशदान", "Contribution"), ("₹55 से ₹200 प्रति माह, उम्र के अनुसार", "₹55 to ₹200 a month by age")), (("ज़मीन", "Land"), ("2 हेक्टेयर तक खेती योग्य", "Up to 2 hectares cultivable"))],
